,"bytes":{"type":"integer","minimum":0,"description":"Their total size. A blob stops counting the moment it is orphaned (its last record dropped it or was retracted), not when the host finally deletes it, so a member who deletes a file has the room back at once."},"reservedBytes":{"type":"integer","minimum":0,"description":"Bytes reserved by uploads begun and not yet committed, aborted or expired. Counted against `maxBytes`, so two concurrent uploads cannot both fit under a limit only one of them fits."},"reservedFiles":{"type":"integer","minimum":0,"description":"Uploads begun and not yet committed, aborted or expired. Counted against `maxFiles`."}}},"RoomLimits":{"title":"RoomLimits","type":"object","additionalProperties":false,"required":["filesEnabled"],"description":"How much a host is willing to store for one room, at the room and per member. A hosting decision, set by the host and never by anything in the room\'s credentials. An upload must fit every scope at once: the object against the smallest `maxFileBytes` that applies, and the member and the room with the file added.","properties":{"filesEnabled":{"type":"boolean","description":"False refuses every rooms/blobs/* upload for the room. Reads of blobs already stored continue."},"room":{"\$ref":"#/\$defs/ScopeLimits","description":"Limits on the room as a whole."},"member":{"\$ref":"#/\$defs/ScopeLimits","description":"Limits on each member\'s own uploads in this room, unless that member has an override. A member is the subject at the root of the authority chain they present, never the key that signed, so an agent acting on an attenuated chain spends its member\'s allowance. Not applied on a `private` room, where the host cannot tell members apart; the room and object limits still hold there."}}},"RecordPrune":{"title":"RecordPrune","type":"object","additionalProperties":false,"required":["version","at","removed"],"description":"The mark a prune leaves: **that** records were removed, when, and how many — nev